    "sys.str_163": "\u0627\u0644\u062F\u062E\u0648\u0644 \u0644\u0644\u0646\u0638\u0627\u0645 (Portal)",
    "sys.str_164": "\u0643\u0644\u0645\u0629 \u0627\u0644\u0645\u0631\u0648\u0631 \u063A\u064A\u0631 \u0635\u062D\u064A\u062D\u0629",
    "sys.str_165": "\u0623\u062F\u062E\u0644 \u0627\u0644\u0631\u0645\u0632 \u0627\u0644\u0633\u0631\u064A \u0627\u0644\u0641\u0627\u0626\u0642...",
    "sys.str_166": "\u0646\u0638\u0627\u0645 \u0627\u0644\u062A\u062D\u0643\u0645 \u0627\u0644\u0633\u064A\u0627\u062F\u064A (SaaS)",
    "sys.str_167": "\u0627\u0644\u0639\u0648\u062F\u0629 \u0644\u0644\u0645\u0648\u0642\u0639",
    "sys.str_168": "\u062C\u0627\u0631\u064A \u0627\u0644\u062A\u062D\u0645\u064A\u0644...",
    "sys.str_169": "\u0644\u0648\u062D\u0629 \u0627\u0644\u0625\u062F\u0627\u0631\u0629 \u0627\u0644\u0645\u0631\u0643\u0632\u064A\u0629 (Master Panel)",
    "sys.str_170": "\u0625\u062F\u0627\u0631\u0629 \u0627\u0634\u062A\u0631\u0627\u0643\u0627\u062A \u0627\u0644\u0645\u062A\u0627\u062C\u0631 \u0648\u0627\u0644\u0634\u0631\u0643\u0627\u062A (SaaS Billing)",
    "sys.str_171": "\u0627\u0644\u0639\u062F\u062F \u0627\u0644\u0643\u0644\u064A \u0644\u0644\u0634\u0631\u0643\u0627\u062A:",
    "sys.str_172": "\u{1F3E2} \u0639\u062F\u062F \u0627\u0644\u0641\u0631\u0648\u0639:",
    "sys.str_173": "\u{1F4C5} \u0635\u0627\u0644\u062D \u062D\u062A\u0649:",
