    "sys.str_175": "+ \u062A\u062C\u062F\u064A\u062F 30 \u064A\u0648\u0645",
    "sys.str_176": "\u0625\u064A\u0642\u0627\u0641 \u0641\u0648\u0631\u064A",
    "sys.str_177": "\u0647\u0644 \u0623\u0646\u062A \u0645\u062A\u0623\u0643\u062F \u0645\u0646 \u062A\u0646\u0641\u064A\u0630 \u0647\u0630\u0627 \u0627\u0644\u0625\u062C\u0631\u0627\u0621\u061F",
    "sys.str_178": "\u0641\u0634\u0644 \u062A\u0646\u0641\u064A\u0630 \u0627\u0644\u0625\u062C\u0631\u0627\u0621",
