    "pos.str_183": "\u062A\u062D\u062F\u064A\u062F \u0627\u0644\u0639\u0645\u064A\u0644 (\u0646\u0642\u0627\u0637 \u0627\u0644\u0648\u0644\u0627\u0621)",
    "pos.str_184": "\u062A\u0637\u0628\u064A\u0642",
