    "sys.str_124": "Electronic copy - does not require an official stamp",
    "sys.str_125": "\u{1F5A8}\uFE0F Printing the bond",
    "sys.str_126": "You are offline",
    "sys.str_127": "Please check your network connection and the system will re-sync immediately.",
    "sys.str_128": "Subscription has ended! \u26A0\uFE0F",
    "sys.str_129": "Sorry, your store's subscription to the Nama Invest cloud platform has expired. Temporary permissions are withheld until the approved package is renewed.",
    "sys.str_130": "To reactivate your store, please contact technical support or pay the pending invoice.",
    "sys.str_131": "Contact support \u{1F4AC}",
    "sys.str_132": "Log out",
    "sys.str_133": "Why choose Nama Invest as the best ERP system in Saudi Arabia?",
    "sys.str_134": "Nama Invest is the most powerful integrated cloud system in the Arab world for managing points of sale (POS), dual accounting, and human resources. Specifically designed to fully comply with ZATCA Phase 2 requirements.",
    "sys.str_135": "Linking the Zakat and Income Tax Authority (ZATCA Phase 2)",
    "sys.str_136": "The Namasoft system automates the process of Cryptographic Stamping and creating Quick Response Codes (QR Codes) in real time, to ensure full compliance with Saudi electronic invoicing laws without any manual intervention.",
    "sys.str_137": "Cloud POS",
    "sys.str_138": "Fast and reliable cashier system that supports offline mode. It synchronizes sales and inventory directly between all branches of the organization the moment connectivity is restored, making it the best choice for markets and restaurants.",
    "sys.str_139": "Accounting and Financial Guidance (Double Entry API)",
    "sys.str_140": "A powerful accounting engine that generates daily entries (Journal Entries) for any movement in the program (sales, purchases, returns, salaries). It has an intelligent tree of accounts, final reports, and income statements based on global financial foundations.",
    "sys.str_141": "Inventory and HR Management (ERP)",
    "sys.str_142": "Accurate management of item movement, warehouses, inventory, and manufacturing. This is matched by an integrated HR system for managing shifts, salaries, vacations, and debts to create a closed loop for a successful business.",
    "sys.str_143": "Move towards the smart financial future",
    "sys.str_144": "Contact us now to establish your company for free and start using the most powerful point of sale system in Saudi Arabia.",
    "sys.str_145": "Chat with us on WhatsApp",
    "sys.str_146": "or",
    "sys.str_147": "Register with a Google account",
    "sys.str_148": "Default account: admin / admin",
    "sys.str_149": "Preparing the login environment...",
    "sys.str_150": "Nama Invest",
    "sys.str_151": "The server sent an invalid response (status:",
